CHAPTERS = tuple(
    (slug, COPY[slug]["xtech"][0], COPY[slug]["xtech"][1])
    for slug in COPY
)


def chapter(slug: str, style: str | None = None) -> tuple[int, str, str]:
    """Return the chapter index and its selected X-LEX title/body."""
    normalized = xlex.normalize_style(style)
    for index, (key, _title, _body) in enumerate(CHAPTERS):
        if key == slug:
            title, body = COPY[key][normalized]
            return index, title, body
    raise KeyError(slug)
